"""Read-only summary of node workflow tables."""
import argparse
from datetime import datetime, timedelta, timezone
import json
from pathlib import Path
import re


REQUIRED = {
    "routines": {"name", "every", "last_time", "last_code"},
    "schedule": {"name", "at", "claimed"},
}
PERIODS = {"s": 1, "m": 60, "h": 3600, "d": 86400}


def timestamp(value, now):
    stamp = datetime.fromisoformat(value)
    return stamp if stamp.tzinfo is not None else stamp.replace(tzinfo=now.tzinfo)


def read_table(node, name):
    try:
        with (node / "wf" / (name + ".json")).open(encoding="utf-8") as stream:
            table = json.load(stream, parse_constant=lambda value: (_ for _ in ()).throw(ValueError(value)))
    except FileNotFoundError:
        return [], []
    except (OSError, UnicodeError, ValueError):
        return [], [{"table": name, "row": None, "why": "bad_table"}]
    if (not isinstance(table, dict) or table.get("contract") != "wf-table/1"
            or not isinstance(table.get("columns"), list)
            or not all(isinstance(col, str) for col in table["columns"])
            or not isinstance(table.get("rows"), list)):
        return [], [{"table": name, "row": None, "why": "bad_table"}]
    return table["rows"], []


def routine(row, now):
    match = re.fullmatch(r"([1-9][0-9]*)([rsmhd])", row["every"])
    if match is None:
        raise ValueError("invalid period")
    last = timestamp(row["last_time"], now) if row["last_time"] else None
    raw_code = row["last_code"]
    if raw_code == "":
        code = None
    elif raw_code == "running":
        code = "running"
    elif re.fullmatch(r"[+-]?[0-9]+", raw_code):
        code = int(raw_code)
    else:
        raise ValueError("invalid code")
    next_time = None
    if last is not None and match[2] != "r":
        next_time = last + timedelta(seconds=int(match[1]) * PERIODS[match[2]])
    if code == "running":
        state = "running"
    elif last is None:
        state = "never"
    elif isinstance(code, int) and code != 0:
        state = "failed"
    elif next_time is not None and now >= next_time:
        state = "overdue"
    else:
        state = "ok"
    rendered = next_time.astimezone(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ") if next_time else None
    return {"name": row["name"], "every": row["every"],
            "last_time": row["last_time"] or None, "last_code": code,
            "state": state, "next": rendered}


def scheduled(row, now):
    at = timestamp(row["at"], now)
    state = "interrupted" if row["claimed"] else "due" if at <= now else "pending"
    return {"name": row["name"], "at": row["at"], "state": state}


def summarize(node, now):
    result = {"v": 1, "routines": [], "schedule": [], "counts": {}, "bad": []}
    for name, states in (("routines", ("running", "never", "failed", "overdue", "ok")),
                         ("schedule", ("interrupted", "due", "pending"))):
        rows, bad = read_table(node, name)
        result["bad"].extend(bad)
        seen = set()
        for index, row in enumerate(rows):
            value = row.get("name") if isinstance(row, dict) else None
            if isinstance(value, str) and value:
                if value in seen:
                    result["bad"].append({"table": name, "row": index, "why": "dup_name"})
                    continue
                seen.add(value)
            if (not isinstance(row, dict) or not isinstance(value, str) or not value
                    or not REQUIRED[name].issubset(row)
                    or not all(isinstance(item, str) for item in row.values())):
                result["bad"].append({"table": name, "row": index, "why": "bad_row"})
                continue
            try:
                item = routine(row, now) if name == "routines" else scheduled(row, now)
            except ValueError:
                result["bad"].append({"table": name, "row": index, "why": "bad_row"})
                continue
            result[name].append(item)
        result[name].sort(key=lambda item: item["name"])
        result["counts"][name] = {
            state: sum(item["state"] == state for item in result[name]) for state in states
        }
    result["bad"].sort(key=lambda item: (item["table"], -1 if item["row"] is None else item["row"], item["why"]))
    return result


def main(argv=None):
    parser = argparse.ArgumentParser(description="Summarize workflow tables without writing to the node")
    parser.add_argument("folder", type=Path)
    parser.add_argument("--now", required=True)
    args = parser.parse_args(argv)
    try:
        now = datetime.fromisoformat(args.now)
    except ValueError:
        parser.error("--now must be an ISO timestamp with a timezone")
    if now.tzinfo is None:
        parser.error("--now must have a timezone")
    if not args.folder.is_dir():
        parser.error("folder must be a directory")
    print(json.dumps(summarize(args.folder, now), separators=(",", ":")))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
